window.DOSIK=window.DOSIK||{};DOSIK["yc_counseltheory"]={"1":[{"t":"tree","title":"상담의 개념","root":"상담","branches":[["성격","내담자의 의사결정과 문제해결을 돕는 활동 · 내담자의 긍정적인 변화와 성장을 목표로 한다"],["구성요소","상담자, 내담자, 상담관계가 상담의 주요 구성요소이다"],["형태","대면 상담으로만 이루어지는 것은 아니다 · 2인 이상의 내담자를 동시에 상담하기도 한다"],["상담과정","내담자의 적극적인 참여를 필요로 한다 · 상담자는 내담자의 자유로운 감정표현을 허용한다"]]},{"t":"table","title":"상담관계","head":["항목","내용"],"rows":[["기초","상담관계를 기초로 상담의 목적을 이루어간다"],["형성 방식","직접 대면으로 형성되거나 전화, 인터넷, 문자 등의 매체를 통해 형성된다"],["바람직한 위치","상담자와 내담자가 대등한 위치에서 상담에 참여하는 것이 바람직하다"],["올바르지 않으면","상담관계가 올바르게 형성되지 않으면 상담의 효율적 진행은 불가능해진다"]]},{"t":"def","term":"상담자의 자질","text":"상담자는 상담에 대한 전문적, 인간적, 윤리적 자질을 갖추어야 한다"}],"2":[{"t":"vs","title":"상담자의 윤리","cols":[{"name":"정보 제공","items":["법원의 정보공개 요청 사실을 내담자에게 알리고 최소한의 정보를 법원에 제공하였다"]},{"name":"전문성","items":["자기의 능력 및 기법의 한계를 인식하고, 전문적 기준에 위배되는 활동을 하지 않는다","검증되지 않고 훈련받지 않은 상담기법의 오ㆍ남용을 하지 않도록 유의한다"]}]},{"t":"def","term":"청소년 상담자","text":"청소년 기본법에 따라 청소년의 권리와 책임을 다할 수 있게 지원해야 한다 · 청소년 관련 정책, 규칙, 법규 등에 대해 정통해야 하고 청소년 내담자를 보호하며 내담자가 최선의 발달을 이루도록 노력해야 한다"}],"3":[{"t":"flow","title":"상담의 진행","steps":["접수면접","초기단계: 내담자와의 상담관계 형성이 중요, 상담구조화를 실시","중기단계: 대안을 찾아 실천","종결단계: 종결에 대한 감정을 다룸","추후상담을 활용할 수 있다"]},{"t":"vs","title":"종결 판단","cols":[{"name":"상담 성과가 있었다면","items":["종결을 고려한다","상담 종결 후, 상담이 필요한 다른 사안이 발생하면 다시 상담을 받을 수 있다"]},{"name":"상담 성과가 충분치 않다면","items":["종결을 논하거나 다른 접근방법이나 절차를 강구한다"]}]},{"t":"table","title":"상담 문서","head":["문서","내용"],"rows":[["상담신청서","상담 신청 시 작성하며 내담자에 관한 최소한의 정보가 수록된다"],["상담기록부 파일","상담관리를 위한 것으로 내담자의 이름과 일련번호가 기록된다"],["상담회기보고서","상담의 진행과정을 기록한 문서이다"],["상담종결보고서","상담 시작에서 종결까지 진행되어 온 상담과정의 요약과 상담 성과의 평가가 포함된다"]]}],"4":[{"t":"def","term":"자기개방","text":"자기공개, 자기노출, 자기폭로라고 불린다"},{"t":"tree","title":"자기개방의 목적","root":"자기개방","branches":[["관계","상담자와 내담자 간 동질감을 형성하게 한다"],["학습","모델링 학습의 목적으로 사용한다"],["변화","변화가능성과 도전을 위한 용기를 불어넣고자 할 때 사용한다"]]}],"5":[{"t":"tree","title":"정신분석의 인간관","root":"정신분석","branches":[["결정론","인간에 대한 결정론적 입장을 취한다 · 인간은 과거 경험에 영향을 받는 존재이다"],["본능","인간행동은 생물학적인 본능과 충동에 의해 동기화 된다 · 성적 추동은 인간의 가장 기본적인 욕구이다"],["의식수준","의식수준을 의식, 전의식, 무의식으로 구분한다"],["자아","자아는 현실원리에 따라 본능적 욕구와 외적인 현실 세계를 중재한다"],["불안","불안을 느끼게 되면 방어기제가 작동된다"],["탐색","개인의 행동을 이해하기 위해 어린 시절의 경험을 탐색한다"]]}],"6":[{"t":"table","title":"대상관계이론 개념","head":["개념","뜻"],"rows":[["과도적 대상(transitional object)","곰 인형, 담요 등이 그 역할을 한다"],["내적 대상","외적 대상에 대해 갖는 이미지, 감정, 생각, 기억 등을 의미한다"],["대상항상성(object constancy)","양육자에 대한 일관된 상을 유지할 수 있는 능력을 의미한다"],["분열(splitting)","좋아하는 간식을 주지 않는 엄마의 모든 면을 나쁘다고 보는 아이가 예에 해당한다"]]}],"8":[{"t":"tree","title":"인간중심 상담","root":"인간중심 상담(로저스)","branches":[["인간관","모든 인간은 자기실현경향성을 가지고 태어난다"],["부적응 원인","유기체적 경험과 자기개념 간의 불일치는 심리적 부적응의 원인이다"],["상담자 태도","내담자에 대한 진실성, 무조건적 긍정적 존중, 공감적 이해를 중시한다"],["목표","궁극적인 목표는 내담자가 온전히 기능하도록 돕는 것이다"]]},{"t":"def","term":"일치성(진실성)","text":"자신의 경험과 자기를 일치시킬 수 있어야 한다 · 자신을 부정하지 않고 자기 자신으로 존재한다 · 자신의 전문역할 뒤로 숨지 않는 것을 뜻한다 · 자신의 능력을 과장하려는 유혹을 성찰하는 것이다"}],"9":[{"t":"tree","title":"게슈탈트 상담","root":"게슈탈트 상담","branches":[["초점","‘지금-여기’에서 경험하는 것들에 초점을 맞춘다"],["직면","내담자가 회피하려는 행동을 직면시킨다"],["실험","내담자의 자기인식과 문제해결을 돕기 위해 다양한 실험을 활용한다"],["목표","내담자가 실존적 삶을 살아가도록 돕는다"]]}],"11":[{"t":"table","title":"행동주의 기법","head":["기법","내용"],"rows":[["체계적 둔감법","고전적 조건형성과 상호제지원리를 토대로 하였다"],["반응대가","교통법규를 위반했을 때 내는 과태료"],["내현적 모델링","모델을 관찰할 수 없을 때, 내담자가 모델의 행동을 시각적으로 떠올려 보도록 하는 기법이다"],["자극통제","다이어트를 위해 친구들과 만나는 약속을 자제하는 것"]]}],"12":[{"t":"tree","title":"벡의 인지모형","root":"인지치료(벡) · 자가치료(self-treatment)의 철학을 강조한다","branches":[["인지도식","과거경험을 일반화한 인지적 구조로 자신과 세상 등에 대한 신념으로 구성된다"],["핵심신념","개인이 어떻게 생각하고 느끼고 행동하는지에 대한 기본이 된다"],["중간신념","핵심신념으로부터 나온 태도, 규칙, 기대, 가정 등으로 구성된다 · 삶에 대한 태도, 규범, 기대 등으로 구성된다"],["자동적 사고","매우 빠르게 의식 속을 지나간다 · 사실인 것처럼 무비판적으로 받아들이게 된다"]]},{"t":"flow","title":"신념의 층","steps":["핵심신념","중간신념은 핵심신념으로부터 나온 것이다","자동적 사고"]}],"13":[{"t":"tree","title":"합리정서행동치료","root":"합리정서행동치료(엘리스)","branches":[["인간관","인간은 합리적인 동시에 비합리적인 존재이다"],["상담자 역할","상담자는 지시적이고 적극적인 역할을 수행한다"],["장애 원인","특정 장애의 원인을 구체적으로 제시하지 않는다"],["비합리적 신념","‘내가 원하는 대로 일이 풀리지 않는 것은 끔찍하다.’"]]}],"17":[{"t":"tree","title":"해결중심단기치료","root":"해결중심단기치료","branches":[["목표","내담자가 중요하다고 생각하는 것을 상담목표로 세운다 · 내담자가 원하는 것을 상담목표로 설정한다"],["자원","문제 해결에 필요한 자원을 내담자 자신이 갖고 있다고 본다 · 내담자의 장점과 자원을 확인하고 지지한다"],["초점","긍정적 예외상황 탐색, 새로운 해결책 도출에 초점을 둔다"],["자세","‘잘 알지 못함(not-knowing)’의 자세를 취하고 내담자를 전문가로 여긴다"]]},{"t":"table","title":"해결중심 질문과 과제","head":["기법","내용"],"rows":[["악몽질문","기적질문, 예외질문 등이 효과가 없을 때 주로 사용된다"],["변화 질문","상담에 오기 전 변화에 대해 질문한다"],["과제","고객형 내담자에게 관찰 또는 행동 과제를 부여한다"]]}],"19":[{"t":"tree","title":"여성주의 상담","root":"여성주의 상담","branches":[["관점","여성의 삶의 맥락에 주목한다 · 다양한 정체성을 가진 위험ㆍ취약 집단 여성에 주목한다 · 여성이 사회적으로 여전히 존재하는 성차별주의와 분투 중이라 본다"],["문제 개념화","개인-체제 간 균형잡힌 관점으로 문제의 원인을 개념화한다 · 내담자의 문제를 유발한 사회ㆍ문화적 요인에 초점을 맞춘다 · 남성과 여성의 성역할 및 행동의 차이는 사회화에 기인한 것으로 본다"],["관계","상담자와 내담자의 평등한 관계를 지향한다"],["내담자 조력","내담자 자신의 경험과 판단을 신뢰하도록 격려한다 · 내담자가 강점 인식 및 자기 옹호를 배우도록 조력한다 · 내담자가 힘을 회복하여 자신의 권리를 지킬 수 있도록 한다"],["사회 참여","정치적 행동을 취할 필요가 있는 사회 문제를 인식한다 · 내담자에게 필요한 자원 및 지지 제공을 위해 지역사회 내 단체, 지도자, 교장 등과 협력한다"]]}]};
